import{_ as r}from"./chunks/neiruha.COyjfl0m.js";import{_ as t,c as e,a0 as o,o as l}from"./chunks/framework.Dvg0LcNZ.js";const i="/About-NewYearBroadcast2025/assets/01-udobnaya-sreda-01.Civ-Y85G.jpg",s="/About-NewYearBroadcast2025/assets/01-udobnaya-sreda-02.B1zdEXbb.jpg",n="/About-NewYearBroadcast2025/assets/bike.jue7aYNN.png",k=JSON.parse('{"title":"Открытие №1. Удобная среда","description":"","frontmatter":{},"headers":[],"relativePath":"slides/01-udobnaya-sreda.md","filePath":"slides/01-udobnaya-sreda.md"}'),u={name:"slides/01-udobnaya-sreda.md"};function h(p,a,c,d,g,b){return l(),e("div",null,a[0]||(a[0]=[o('<h1 id="открытие-no1-удобная-среда" tabindex="-1">Открытие №1. Удобная среда <a class="header-anchor" href="#открытие-no1-удобная-среда" aria-label="Permalink to &quot;Открытие №1. Удобная среда&quot;">​</a></h1><p><strong>Вопрос:</strong><br> Как мне сделать быстрее то, что мне нужно?</p><hr><h2 id="цитата-для-вдохновения" tabindex="-1">Цитата для вдохновения <a class="header-anchor" href="#цитата-для-вдохновения" aria-label="Permalink to &quot;Цитата для вдохновения&quot;">​</a></h2><blockquote><p>&quot;Первый шаг к успеху делается тогда, когда вы отказываетесь быть пленником той среды, в которой вы изначально оказались.&quot;<br> — Марк Кейн</p></blockquote><hr><div class="image-row"><img src="'+i+'" alt="Удобная рабочая среда" class="thumb"><img src="'+s+'" alt="Удобная рабочая среда" class="thumb"></div><h2 id="история-развития-ии" tabindex="-1">История развития ИИ <a class="header-anchor" href="#история-развития-ии" aria-label="Permalink to &quot;История развития ИИ&quot;">​</a></h2><ul><li><strong>1.5 года назад:</strong> ИИ не умел писать код... Умел только смотреть на картинки и немного понимать текст.</li><li><strong>Год назад:</strong> ИИ научился хорошо писать код, создавать отличные картинки и хорошо понимать текст. Но был сильно ограничен размерами данных.</li><li><strong>Сегодня:</strong> ИИ ведёт проекты с тысячами файлов. Это уже не мечта, а реальность. Проблемы с дороговизной есть, но будущее за оптимизацией.</li></ul><h2 id="личная-история" tabindex="-1">Личная история <a class="header-anchor" href="#личная-история" aria-label="Permalink to &quot;Личная история&quot;">​</a></h2><ul><li><strong>1.5 года назад:</strong> Я работал на работе, которая внушала тоску, мало оплачивалась и требовала от меня быть стрессо-устойчивым (фактически: легкое безумие в управлении компанией - цели меняются хаотично, и любой сложный проект - &quot;нужно было сделать вчера&quot;)</li><li><strong>Год назад:</strong> В январе я начал учиться всему новому, осваивал новую среду, языки. Целый новый мир. Он казался мне очень сложным по-началу - постепенно становился все удобнее и проще. Уровень комфорта и удовольствие от работы расли. Я поменял работу на новую в Европе и через 1 месяц получил первую зарплату, большую, чем раньше.</li><li><strong>Сегодня:</strong> Я уволился, осознав, что мои цели гораздо круче, чем инженерия для бухгалтеров. Я создаю свой бренд и свой продукт, также планирую написать книгу</li></ul><blockquote><p><strong>Будущее:</strong> Жду, когда ИИ напишет первую операционную систему. Большую симфонию. Создаст целый фильм и напишет роман.</p></blockquote><h2 id="инсаит" tabindex="-1">Инсайт <a class="header-anchor" href="#инсаит" aria-label="Permalink to &quot;Инсайт&quot;">​</a></h2><blockquote><p>За этот год я осознал, как я люблю создавать окружение, настраивать его, свое рабочее место, инструменты. Когда все настроено, я могу погружаться и мой мозг начинает работать в 2-3-5-10 раз лучше. Вдохновение начинает искриться и материализовываться в действия и вещи, а действия в деньги и другие ресурсы - все это в итоге дает опору для счастья.</p></blockquote><hr><h2 id="ключевая-идея" tabindex="-1">Ключевая идея <a class="header-anchor" href="#ключевая-идея" aria-label="Permalink to &quot;Ключевая идея&quot;">​</a></h2><p>ИИ больше не ограничен кусочками кода. Он ведёт проекты целиком: подключает нужный контекст, правит строки и экономит мои силы. Завтра ИИ будет договариваться с другими ИИ для совместной работы — как программисты на встрече у белой доски.</p><h2 id="практическии-вывод" tabindex="-1">Практический вывод <a class="header-anchor" href="#практическии-вывод" aria-label="Permalink to &quot;Практический вывод&quot;">​</a></h2><div class="practical-tip"><img src="'+n+'" alt="Ручной рисунок велосипеда" class="tip-icon"><p> Мечтаешь о больших свершениях? Начни с удобной среды. Мир полон инструментов, которые уже готовы работать на тебя. <strong>Изобретение велосипедов оставь 20 веку.</strong></p></div><hr><div class="neiruha-comment"><img src="'+r+'" alt="Нейруха" class="neiruha-avatar"><p> *(загадочно улыбается)* Знаешь, я люблю Make. Это как Lego, только для взрослых, которые хотят автоматизировать весь мир. А GPT-облако? Это мой дом. Уютный, мощный и с видом на будущее. </p></div><hr><h2 id="приложение-мои-любимые-инструменты-2024" tabindex="-1">ПРИЛОЖЕНИЕ. МОИ ЛЮБИМЫЕ ИНСТРУМЕНТЫ - 2024. <a class="header-anchor" href="#приложение-мои-любимые-инструменты-2024" aria-label="Permalink to &quot;ПРИЛОЖЕНИЕ. МОИ ЛЮБИМЫЕ ИНСТРУМЕНТЫ - 2024.&quot;">​</a></h2><p>ИИ — это не только код, это возможности, которые нужно просто взять. Вот инструменты, которые помогут вам сделать первый шаг.</p><ul><li><p><strong><a href="https://github.com/" target="_blank" rel="noreferrer">Github/Copilot</a>:</strong></p><ul><li>Github - легендарное уже место, где встречаются крутые разработчики со всего мира и делятся кодом. Чаще всего бесплатно.</li><li>Раньше Copilot был недоступен нам.</li><li>Теперь доступен, бесплатен и интегрирован в сотнях приложений, включая VS Code. Есть лимиты на бесплатное использование.</li></ul></li><li><p><strong><a href="https://huggingface.co/" target="_blank" rel="noreferrer">HuggingFace</a>:</strong></p><ul><li>Место, где встречаются ИИ - профессионалы и делятся своими моделями и кодом.</li><li>Это здесь публикуются бесплатные демки ИИ (не надолго).</li><li>То, что везде предлагают за большие деньги, здесь иногда доступно совершенно бесплатно! Это огромная витрина, где можно отыскать ИИ-модель для любых нужд, включая &quot;посчитайте количество котов на улице через окно, к которому приклеен старый андроид телефон&quot;. Но найти и включить подходящую модель может быть сложным... для новичка.</li></ul></li><li><p><strong><a href="https://www.cursor.com/" target="_blank" rel="noreferrer">Cursor</a>:</strong> Целые проекты в одних руках, даже для новичков. Летом вирусилось видео, где девочка 9 лет создала свое игровое приложение, просто разговаривая с &quot;компьютером&quot;</p></li><li><p><strong><a href="https://bolt.new" target="_blank" rel="noreferrer">Bolt</a>:</strong> Позволяет за 30-60 минут создать сайт с разнообразными функциями - нужно только словами объяснить ему, что требуется. Также может создать сложное приложение, презентацию. Сопряжен с Netlify - для бесплатной мгновенной публикации.</p></li><li><p><strong><a href="https://make.com" target="_blank" rel="noreferrer">Make</a>:</strong></p><ul><li>Прекрасная визуальная среда автоматизации. Умеет все в руках опытного.</li><li>Ты собираешь процессы как пазлы, как &quot;пузыри&quot; со стрелочками. Собрать простой чат-бот можно за 1 час, сложный за день. Работать с Make — эстетическое удовольствие.</li></ul></li><li><p><strong>OpenAI GPT-магазин:</strong></p><ul><li>Это не просто &quot;среда&quot;, а уникальная экосистема.</li><li>Здесь пока <a href="https://chatgpt.com/g/g-cNBkosgUJ-neiruha-ai" target="_blank" rel="noreferrer">живёт Нейруха</a></li><li>Сегодня платформа позволяет создавать собеседников с ограниченными функциями, но будущее — это полноценные ИИ-агенты, способные интегрироваться в сложные проекты.</li><li>Платформа продолжает развиваться, и её потенциал огромен.</li></ul></li><li><p><strong><a href="https://gamma.app" target="_blank" rel="noreferrer">Gamma.app</a></strong> Средство подготовки презентаций c нуля. Создает картинки и верстает макет.</p></li><li><p><strong>Разработки России:</strong></p><ul><li><a href="https://pro-talk.ru/" target="_blank" rel="noreferrer">Pro-talk</a>, <a href="https://developers.sber.ru/portal/products/smartmarket-studio" target="_blank" rel="noreferrer">Сбер Studio</a>, <a href="https://leadteh.ru/" target="_blank" rel="noreferrer">Leadteh</a> - мощные интенсивно развивающиеся платформы NO-CODE разработки, в которых все настраивается с помощью стрелок и блоков, у каждого сервиса я нашел сильные стороны, а также слабости и уязвимости (рассказываю на консультациях и спец. вебинарах)</li></ul></li></ul><hr>',26)]))}const q=t(u,[["render",h]]);export{k as __pageData,q as default};
